!   [1] the OMP-preserving merged us_exx closure (generated by
!       f2dace-qe-source/run_regex_omp_newdxx_g.py from the QE 7.6 export
!       src_f90_vexx_preprocessed; PW/src/us_exx.f90 verified identical
!       to the pristine /workspace/qe-omp2/q-e tree)
!   [2] QE utility stubs (no-op clocks, loud errore)
! Regeneration: python3 f2dace-qe-source/run_regex_omp_newdxx_g.py
!# 1 "kind.f90"
!# 1 "<built-in>"
!# 1 "<command-line>"
!# 1 "/workspace/q-e/Modules//"
