      SUBROUTINE mp_sum_rm1_nc(msg, k1, k2, gid)
        ! for non-contiguous 1D arrays  
        IMPLICIT NONE
        REAL (8), INTENT (INOUT) :: msg(:)
        INTEGER, INTENT (IN) :: gid
        INTEGER, INTENT (IN) :: k1, k2

        REAL(8), ALLOCATABLE :: msg_buff(:)
        INTEGER :: msglen
        IF ( k2-k1+1 < 1 ) RETURN
        ALLOCATE( msg_buff(k2-k1+1) )
        msg_buff(1:k2-k1+1)=msg(k1:k2)
        msglen = size(msg_buff)
        CALL reduce_base_real( msglen, msg_buff, gid, -1 )
        msg(k1:k2)=msg_buff(1:k2-k1+1)
        DEALLOCATE( msg_buff )

      END SUBROUTINE mp_sum_rm1_nc


      SUBROUTINE mp_sum_rm2_nc(msg, k1, k2, k3, k4, gid)
        ! for non-contiguous 2D arrays  
        IMPLICIT NONE
        REAL (8), INTENT (INOUT) :: msg(:,:)
        INTEGER, INTENT (IN) :: gid
        INTEGER, INTENT (IN) :: k1, k2, k3, k4

        REAL(8), ALLOCATABLE :: msg_buff(:,:)
        INTEGER :: msglen
        IF ( min(k2-k1+1,k4-k3+1) < 1 ) RETURN
        ALLOCATE( msg_buff(k2-k1+1,k4-k3+1) )
        msg_buff(1:k2-k1+1,1:k4-k3+1)=msg(k1:k2,k3:k4)
        msglen = size(msg_buff)
        CALL reduce_base_real( msglen, msg_buff, gid, -1 )
        msg(k1:k2,k3:k4)=msg_buff(1:k2-k1+1,1:k4-k3+1)
        DEALLOCATE( msg_buff )

      END SUBROUTINE mp_sum_rm2_nc

      SUBROUTINE mp_root_sum_rm( msg, res, root, gid )
        USE parallel_include
        IMPLICIT NONE
        REAL (8), INTENT (IN)  :: msg(:,:)
        REAL (8), INTENT (OUT) :: res(:,:)
        INTEGER,   INTENT (IN)  :: root
        INTEGER,   INTENT (IN) :: gid

        INTEGER :: msglen, ierr, taskid

        msglen = size(msg)

        CALL mpi_comm_rank( gid, taskid, ierr)
        IF( ierr /= 0 ) CALL mp_stop( 8059 )
        !
        IF( taskid == root ) THEN
           IF( msglen > size(res) ) CALL mp_stop( 8060 )
        END IF

        CALL reduce_base_real_to( msglen, msg, res, gid, root )







      END SUBROUTINE mp_root_sum_rm


      SUBROUTINE mp_root_sum_cm( msg, res, root, gid )
        USE parallel_include
        IMPLICIT NONE
        COMPLEX (8), INTENT (IN)  :: msg(:,:)
        COMPLEX (8), INTENT (OUT) :: res(:,:)
        INTEGER,   INTENT (IN)  :: root
        INTEGER,  INTENT (IN) :: gid

        INTEGER :: msglen, ierr, taskid

        msglen = size(msg)

        CALL mpi_comm_rank( gid, taskid, ierr)
        IF( ierr /= 0 ) CALL mp_stop( 8061 )

        IF( taskid == root ) THEN
           IF( msglen > size(res) ) CALL mp_stop( 8062 )
        END IF

        CALL reduce_base_real_to( 2 * msglen, msg, res, gid, root )







      END SUBROUTINE mp_root_sum_cm

