! GNU General Public License. See the file `License'
! in the root directory of the present distribution,
! or http://www.gnu.org/copyleft/gpl.txt .
!
!----------------------------------------------------------------------------
MODULE constants
  !----------------------------------------------------------------------------
  !! The constants needed everywhere
  !
  USE kinds, ONLY : DP
  !
  IMPLICIT NONE
  !
  SAVE
  !
  ! ... Mathematical constants
  ! 
  REAL(8), PARAMETER :: pi     = 3.14159265358979323846_8 
  REAL(8), PARAMETER :: tpi    = 2.0_8 * pi
  REAL(8), PARAMETER :: fpi    = 4.0_8 * pi
  REAL(8), PARAMETER :: sqrtpi = 1.77245385090551602729_8 
  REAL(8), PARAMETER :: sqrtpm1= 1.0_8 / sqrtpi
  REAL(8), PARAMETER :: sqrt2  = 1.41421356237309504880_8
  !
  ! ... Physical constants, SI (NIST 2018)
  !     http://physics.nist.gov/constants
  !
  REAL(8), PARAMETER :: H_PLANCK_SI      = 6.62607015E-34_8      ! J s
  REAL(8), PARAMETER :: K_BOLTZMANN_SI   = 1.380649E-23_8        ! J K^-1 
  REAL(8), PARAMETER :: ELECTRON_SI      = 1.602176634E-19_8     ! C
  REAL(8), PARAMETER :: ELECTRONVOLT_SI  = 1.602176634E-19_8     ! J  
  REAL(8), PARAMETER :: ELECTRONMASS_SI  = 9.1093837015E-31_8    ! Kg
  REAL(8), PARAMETER :: HARTREE_SI       = 4.3597447222071E-18_8 ! J
  REAL(8), PARAMETER :: RYDBERG_SI       = HARTREE_SI/2.0_8      ! J
  REAL(8), PARAMETER :: BOHR_RADIUS_SI   = 0.529177210903E-10_8  ! m
  REAL(8), PARAMETER :: AMU_SI           = 1.66053906660E-27_8  ! Kg
  REAL(8), PARAMETER :: C_SI             = 2.99792458E+8_8    ! m sec^-1
  REAL(8), PARAMETER :: MUNOUGHT_SI      = fpi*1.0E-7_8       ! N A^-2
  REAL(8), PARAMETER :: EPSNOUGHT_SI     = 1.0_8 / (MUNOUGHT_SI * &
                                                       C_SI**2) ! F m^-1
  !
  ! ... Physical constants, atomic units:
  ! ... AU for "Hartree" atomic units (e = m = hbar = 1)
  ! ... RY for "Rydberg" atomic units (e^2=2, m=1/2, hbar=1)
  !
  REAL(8), PARAMETER :: K_BOLTZMANN_AU   = K_BOLTZMANN_SI / HARTREE_SI
  REAL(8), PARAMETER :: K_BOLTZMANN_RY   = K_BOLTZMANN_SI / RYDBERG_SI
  !
  ! ... Unit conversion factors: energy and masses
  !
  REAL(8), PARAMETER :: AUTOEV           = HARTREE_SI / ELECTRONVOLT_SI
  REAL(8), PARAMETER :: RYTOEV           = AUTOEV / 2.0_8
  REAL(8), PARAMETER :: AMU_AU           = AMU_SI / ELECTRONMASS_SI
  REAL(8), PARAMETER :: AMU_RY           = AMU_AU / 2.0_8
  !
  ! ... Unit conversion factors: atomic unit of time, in s and ps
  !
  REAL(8), PARAMETER :: AU_SEC           = H_PLANCK_SI/tpi/HARTREE_SI
  REAL(8), PARAMETER :: AU_PS            = AU_SEC * 1.0E+12_8
  !
  ! ... Unit conversion factors: pressure (1 Pa = 1 J/m^3, 1GPa = 10 Kbar )
  !
  REAL(8), PARAMETER :: AU_GPA           = HARTREE_SI / BOHR_RADIUS_SI ** 3 &
                                            / 1.0E+9_8 
  REAL(8), PARAMETER :: RY_KBAR          = 10.0_8 * AU_GPA / 2.0_8
  !
  ! ... Unit conversion factors: 1 debye = 10^-18 esu*cm 
  ! ...                                  = 3.3356409519*10^-30 C*m 
  ! ...                                  = 0.208194346 e*A
  ! ... ( 1 esu = (0.1/c) Am, c=299792458 m/s)
  !
  REAL(8), PARAMETER :: DEBYE_SI         = 3.3356409519_8 * 1.0E-30_8 ! C*m 
  REAL(8), PARAMETER :: AU_DEBYE         = ELECTRON_SI * BOHR_RADIUS_SI / &
                                            DEBYE_SI
  !
  REAL(8), PARAMETER :: eV_to_kelvin = ELECTRONVOLT_SI / K_BOLTZMANN_SI
  REAL(8), PARAMETER :: ry_to_kelvin = RYDBERG_SI / K_BOLTZMANN_SI
  !
  ! .. Unit conversion factors: Energy to wavelength
  !
  REAL(8), PARAMETER :: EVTONM = 1E+9_8 * H_PLANCK_SI * C_SI / &
                                  &ELECTRONVOLT_SI
  REAL(8), PARAMETER :: RYTONM = 1E+9_8 * H_PLANCK_SI * C_SI / RYDBERG_SI
  !
  !  Speed of light in atomic units
  !
  REAL(8), PARAMETER :: C_AU             = C_SI / BOHR_RADIUS_SI * AU_SEC
  !
  ! ... zero up to a given accuracy
  !
  REAL(8), PARAMETER :: eps4  = 1.0E-4_8
  REAL(8), PARAMETER :: eps6  = 1.0E-6_8
  REAL(8), PARAMETER :: eps8  = 1.0E-8_8
  REAL(8), PARAMETER :: eps12 = 1.0E-12_8
  REAL(8), PARAMETER :: eps14 = 1.0E-14_8
  REAL(8), PARAMETER :: eps16 = 1.0E-16_8
  REAL(8), PARAMETER :: eps24 = 1.0E-24_8
  REAL(8), PARAMETER :: eps32 = 1.0E-32_8
  !
  REAL(8), PARAMETER :: gsmall = 1.0E-12_8
  !
  REAL(8), PARAMETER :: e2 = 2.0_8      ! the square of the electron charge
  REAL(8), PARAMETER :: degspin = 2.0_8 ! the number of spins per level
  !
  !---- COMPATIBIILITY
  !
  REAL(8), PARAMETER :: BOHR_RADIUS_CM = BOHR_RADIUS_SI * 100.0_8
  REAL(8), PARAMETER :: BOHR_RADIUS_ANGS = BOHR_RADIUS_CM * 1.0E8_8
  REAL(8), PARAMETER :: ANGSTROM_AU = 1.0_8/BOHR_RADIUS_ANGS
  REAL(8), PARAMETER :: DIP_DEBYE = AU_DEBYE
  REAL(8), PARAMETER :: AU_TERAHERTZ  = AU_PS
  REAL(8), PARAMETER :: AU_TO_OHMCMM1 = 46000.0_8 ! (ohm cm)^-1
  REAL(8), PARAMETER :: RY_TO_THZ = 1.0_8 / AU_TERAHERTZ / FPI
  REAL(8), PARAMETER :: RY_TO_GHZ = RY_TO_THZ*1000.0_8
  REAL(8), PARAMETER :: RY_TO_CMM1 = 1.E+10_8 * RY_TO_THZ / C_SI
  !
  REAL(8), PARAMETER :: AVOGADRO = 6.02214076D+23

END MODULE constants
!# 1 "recvec.f90"
!# 1 "<built-in>"
!# 1 "<command-line>"
!# 1 "/workspace/q-e/Modules//"
!# 1 "recvec.f90"
!
! Copyright (C) 2010 Quantum ESPRESSO group
! This file is distributed under the terms of the
! GNU General Public License. See the file `License'
! in the root directory of the present distribution,
! or http://www.gnu.org/copyleft/gpl.txt .
!
!=----------------------------------------------------------------------------=!
   MODULE gvect
!=----------------------------------------------------------------------------=!
     !! Variables describing the reciprocal lattice vectors
     !! G vectors with |G|^2 < ecutrho, cut-off for charge density
     !! With gamma tricks, G-vectors are divided into two half-spheres,
     !! G> and G<, containing G and -G (G=0 is in G>)
     !! This is referred to as the "dense" (or "hard", or "thick") grid

     USE kinds, ONLY: DP

     IMPLICIT NONE
     SAVE

     INTEGER :: ngm = 0
     !! local  number of G vectors (on this processor) with gamma tricks, only
     !! vectors in G>
     INTEGER :: ngm_g = 0
     !! global number of G vectors (summed on all procs) in serial execution,
     !! \(\text{ngm}_g = \text{ngm}\).
     INTEGER :: ngl = 0
     !! number of G-vector shells
     INTEGER :: ngmx = 0
     !! local number of G vectors, maximum across all procs

     REAL(8) :: ecutrho = 0.0_8
     !! energy cut-off for charge density 
     REAL(8) :: gcutm = 0.0_8
     !! \(\text{ecutrho}/(2 \pi/a)^2\), cut-off for \(\|G\|^2\)

     INTEGER :: gstart = 2
     !! index of the first G vector whose module is > 0. Needed in parallel
     !execution: gstart=2 for the proc that holds G=0, gstart=1 for all others.

     REAL(8), ALLOCATABLE, TARGET :: gg(:) 
     !! \(G^2\) in increasing order (in units of \(\text{tpiba2}=(2\pi/a)^2\) )

     REAL(8), POINTER, PROTECTED :: gl(:)
     !! gl(i) = i-th shell of G^2 (in units of tpiba2)
     INTEGER, ALLOCATABLE, TARGET, PROTECTED :: igtongl(:)
     !! igtongl(n) = shell index for n-th G-vector
     
     REAL(8), ALLOCATABLE, TARGET :: g(:,:) 
     !! G-vectors cartesian components ( in units \(\text{tpiba} =(2\pi/a)\) )
     !
     INTEGER, ALLOCATABLE, TARGET :: mill(:,:)
     !! miller index of G vectors (local to each processor)
     !! G(:) = mill(1)*bg(:,1)+mill(2)*bg(:,2)+mill(3)*bg(:,3) 
     !! where bg are the reciprocal lattice basis vectors.
     !
     INTEGER, ALLOCATABLE, TARGET :: ig_l2g(:)
     !! converts a local G-vector index into the global index
     !! ("l2g" means local to global): ig\_l2g(i) = index of i-th
     !! local G-vector in the global array of G-vectors
     !
     INTEGER, ALLOCATABLE, TARGET :: mill_g(:,:)
     !! Miller index of all G vectors
     !
     COMPLEX(8), ALLOCATABLE :: eigts1(:,:)
     !! the phases \(e^{-iG\text{tau}_s}\) used to calculate structure factors.
     COMPLEX(8), ALLOCATABLE :: eigts2(:,:), eigts3(:,:)
     !   
   CONTAINS

     SUBROUTINE gvect_init( ngm_ , comm )
       !
       !! Set local and global dimensions, allocate arrays
       !
       USE mp, ONLY: mp_max, mp_sum
       IMPLICIT NONE
       INTEGER, INTENT(IN) :: ngm_
       INTEGER, INTENT(IN) :: comm
       !! communicator of the group on which g-vecs are distributed
       !
       ngm = ngm_
       !
       !  calculate maximum over all processors
       !
       ngmx = ngm
       CALL mp_max( ngmx, comm )
       !
       !  calculate sum over all processors
       !
       ngm_g = ngm
       CALL mp_sum( ngm_g, comm )
       !
       !  allocate arrays - only those that are always kept until the end
       !
       ALLOCATE( gg(ngm) )
       ALLOCATE( g(3, ngm) )
       ALLOCATE( mill(3, ngm) )
       ALLOCATE( ig_l2g(ngm) )
       ALLOCATE( igtongl(ngm) )
       ! FIXME  why dimensions in the following directive?
       !$acc enter data create( mill(1:3,1:ngm), g(1:3,1:ngm), gg(1:ngm), igtongl(1:ngm) ) 
       !
       RETURN 
       !
     END SUBROUTINE gvect_init

     SUBROUTINE deallocate_gvect(vc)
       !! Deallocate G-vector related arrays.
       !
       IMPLICIT NONE
       !
       LOGICAL, OPTIONAL, INTENT(IN) :: vc
       LOGICAL :: vc_
       !
       vc_ = .false.
       IF (PRESENT(vc)) vc_ = vc
       IF ( .NOT. vc_ ) THEN
          IF ( ASSOCIATED( gl ) ) DEALLOCATE ( gl )
       END IF
       !
       !  
       IF( ALLOCATED( gg ) ) THEN
!$acc    exit data delete(gg)
       DEALLOCATE( gg )
       END IF
       IF( ALLOCATED( g ) )  THEN 
!$acc    exit data delete(g) 
         DEALLOCATE( g )
       END IF 
       IF( ALLOCATED( mill_g ) ) DEALLOCATE( mill_g )
       IF( ALLOCATED( mill ) )   THEN 
!$acc    exit data delete(mill) 
         DEALLOCATE( mill )
       END IF 
       IF( ALLOCATED( igtongl )) THEN
!$acc    exit data delete(igtongl)         
         DEALLOCATE( igtongl )
       END IF
       IF( ALLOCATED( ig_l2g ) ) DEALLOCATE( ig_l2g )
       IF( ALLOCATED( eigts1 ) ) THEN
!$acc    exit data delete(eigts1)         
         DEALLOCATE( eigts1 )
       END IF 
       IF( ALLOCATED( eigts2 ) ) THEN
!$acc    exit data delete(eigts2)
         DEALLOCATE( eigts2 )
       END IF 
       IF( ALLOCATED( eigts3 ) ) THEN
!$acc    exit data delete(eigts3)  
         DEALLOCATE( eigts3 )
       END IF 
       !
     END SUBROUTINE deallocate_gvect

     SUBROUTINE deallocate_gvect_exx()
       IF( ALLOCATED( gg ) ) THEN
!$acc    exit data delete(gg)
         DEALLOCATE( gg )
       END IF
       IF( ALLOCATED( g ) )  THEN
!$acc    exit data delete(g) 
         DEALLOCATE( g )
       END IF 
       IF( ALLOCATED( mill ) ) THEN 
!$acc    exit data delete(mill) 
         DEALLOCATE( mill )
       END IF 
       IF( ALLOCATED( igtongl ) ) THEN
!$acc    exit data delete(igtongl)         
         DEALLOCATE( igtongl )
       END IF
       IF( ALLOCATED( ig_l2g ) )  DEALLOCATE( ig_l2g )
     END SUBROUTINE deallocate_gvect_exx
     !
     !-----------------------------------------------------------------------
     SUBROUTINE gshells ( vc )
        !----------------------------------------------------------------------
        !! Calculate number of G shells: ngl, and the index ng = igtongl(ig)
        !! that gives the shell index ng for (local) G-vector of index ig.
        !
        USE kinds,              ONLY : DP
        USE constants,          ONLY : eps8
        !
        IMPLICIT NONE
        !
        LOGICAL, INTENT(IN) :: vc
        !
        INTEGER :: ng, igl
        !
        IF ( vc ) THEN
           !
           ! in case of a variable cell run each G vector has its shell
           !
           ngl = ngm
           gl => gg
           DO ng = 1, ngm
              igtongl (ng) = ng
           ENDDO
        ELSE
           !
           ! G vectors are grouped in shells with the same norm
           !
           ngl = 1
           igtongl (1) = 1
           DO ng = 2, ngm
              IF (gg (ng) > gg (ng - 1) + eps8) THEN
                 ngl = ngl + 1
              ENDIF
              igtongl (ng) = ngl
           ENDDO

           ALLOCATE (gl( ngl))
           gl (1) = gg (1)
           igl = 1
           DO ng = 2, ngm
              IF (gg (ng) > gg (ng - 1) + eps8) THEN
                 igl = igl + 1
                 gl (igl) = gg (ng)
              ENDIF
           ENDDO

           IF (igl /= ngl) CALL errore ('gshells', 'igl <> ngl', ngl)

        ENDIF
!$acc update device(igtongl)         
     END SUBROUTINE gshells
!=----------------------------------------------------------------------------=!
   END MODULE gvect
!# 1 "noncol.f90"
!# 1 "<built-in>"
!# 1 "<command-line>"
!# 1 "/workspace/q-e/Modules//"
!# 1 "noncol.f90"
!
! Copyright (C) 2001-2003 PWSCF group
