! GNU General Public License. See the file `License'
! in the root directory of the present distribution,
! or http://www.gnu.org/copyleft/gpl.txt .
!
!----------------------------------------------------------------------------
!
MODULE noncollin_module
  !
  !! Variables for noncollinear magnetism and spin-orbit interactions
  !
  USE kinds, ONLY : DP
  USE parameters, ONLY : ntypx
  !
  INTEGER :: npol
  !! number of coordinates of wfc
  INTEGER :: report
  !! print the local quantities (magnet. and rho) every #report iterations
  INTEGER :: nspin_lsda = 1
  !! equal to 1 when \(\text{nspin}=1,4\) and to 2 when \(\text{nspin}=2\)
  INTEGER :: nspin_mag = 1
  !! equal to 1 when \(\text{nspin}=1,4\) (\(\text{domag}=\text{FALSE}\)), to 2 when 
  !! \(\text{nspin}=2\) and to 4 when \(\text{nspin}=4\) (\(\text{domag}=\text{TRUE}\))
  INTEGER :: nspin_gga = 1
  !! equal to 1 when \(\text{nspin}=1,4\) (\(\text{domag}=\text{FALSE}\)), equal
  !! to 2 when \(\text{nspin}=2,4\) (\(\text{domag}=\text{TRUE}\)) (needed with GGA)
  INTEGER :: i_cons = 0
  !! indicator for constrained local quantities
  !
  INTEGER, ALLOCATABLE :: pointlist(:)
  !! when spherical (non-overlapping) integration regions are defined around
  !! atoms this index says for each point in the fft grid to which atom
  !! it is assigned (0 if no atom is selected).
  !
  LOGICAL :: noncolin
  !! TRUE if noncollinear magnetism is allowed
  LOGICAL :: domag
  !! TRUE if total magnetization is present, FALSE for nonmagnetic calculation
  LOGICAL :: lsign=.FALSE.
  !! if TRUE use the sign feature to calculate rhoup and rhodw
  INTEGER :: colin_mag = -1
  !! equal to 0 if the system does not have a collinear magnetism
  !! equal to -1 if the collinearity is not checked.
  !! larger than 0 if the system has a collinear magnetism (nspin_mag = 2)
  !! equal to 1 if the symmetries with time-reversal is not detected
  !! equal to 2 if the symmetries with time-reversal is detected

  !
  REAL(8) :: angle1(ntypx)
  !! define the polar coordinates of the starting magnetization
  !! direction for each atom - first angle
  REAL(8) :: angle2(ntypx)
  !! starting mag. direction - second angle.
  REAL(8) :: mcons(3,ntypx)=0.d0
  !! constrained values for local variables
  REAL(8) :: magtot_nc(3)
  !! total magnetization
  REAL(8) :: bfield(3)=0.d0
  !! magnetic field used in some cases
  REAL(8) :: vtcon
  !! contribution of the constraining fields to the total energy
  REAL(8) :: r_m(ntypx)=0.0d0
  !! radius for local integrations for each type
  REAL(8) :: lambda
  !! prefactor in the penalty functional for constraints
  !
  REAL(8), ALLOCATABLE :: factlist(:)
  !! weight factors for local integrations
  REAL(8), ALLOCATABLE :: m_loc(:,:)
  !! local integrated magnetization
  REAL(8) :: ux(3)
  !! versor for deciding signs in GGA
  !
  !! Variables needed for calculations with spin-orbit
  !
  LOGICAL :: lspinorb
  !! if .TRUE. this calculation uses spin-orbit interactions
  LOGICAL :: lforcet
  !! if .TRUE. apply Force Theorem to calculate MAE
  LOGICAL :: starting_spin_angle
  !! if .TRUE. the initial wavefunctions are spin-angle functions.
  !
  SAVE
  !
  CONTAINS
    !
    !------------------------------------------------------------------------
    SUBROUTINE deallocate_noncol()
      !------------------------------------------------------------------------
      !! Deallocates arrays related to noncollinear magnetism.
      !
      IF ( ALLOCATED( pointlist) )       DEALLOCATE( pointlist )
      IF ( ALLOCATED( factlist ) )       DEALLOCATE( factlist )
      IF ( ALLOCATED( m_loc    ) )       DEALLOCATE( m_loc )
      !
    END SUBROUTINE deallocate_noncol
    !
END MODULE noncollin_module
!# 1 "mp_bands.f90"
!# 1 "<built-in>"
!# 1 "<command-line>"
!# 1 "/workspace/q-e/Modules//"
!# 1 "mp_bands.f90"
!
! Copyright (C) 2013 Quantum ESPRESSO group
! This file is distributed under the terms of the
! GNU General Public License. See the file `License'
! in the root directory of the present distribution,
! or http://www.gnu.org/copyleft/gpl.txt .
!
!----------------------------------------------------------------------------
MODULE mp_bands
  !----------------------------------------------------------------------------
  !! Band groups (processors within a pool of bands).  
  !! Subdivision of pool group, used for parallelization over bands.
  !
  USE mp, ONLY : mp_barrier, mp_bcast, mp_size, mp_rank, mp_comm_split
  USE parallel_include
  !
  IMPLICIT NONE 
  SAVE
  !
  INTEGER :: nbgrp = 1
  !! number of band groups
  INTEGER :: nproc_bgrp = 1
  !! number of processors within a band group
  INTEGER :: me_bgrp = 0
  !! index of the processor within a band group
  INTEGER :: root_bgrp = 0
  !! index of the root processor within a band group
  INTEGER :: my_bgrp_id = 0
  !! index of my band group
  INTEGER :: root_bgrp_id = 0
  !! index of root band group
  INTEGER :: inter_bgrp_comm = 0
  !! inter band group communicator
  INTEGER :: intra_bgrp_comm = 0
  !! intra band group communicator  
  !
  LOGICAL :: use_bgrp_in_hpsi = .FALSE.
  !! TRUE if band parallelization is performed inside \( H\psi \)
  !! and \( S\psi \), FALSE otherwise (band parallelization can be 
  !! performed outside \( H\psi \) and \( S\psi \) though).
  !
  ! ... "task" groups (for band parallelization of FFT)
  !
  INTEGER :: ntask_groups = 1
  !! number of proc. in an orbital "task group"
  !
  ! ... "nyfft" groups (to push FFT parallelization beyond the nz-planes limit)
  !
  INTEGER :: nyfft = 1
  !! number of y-fft groups. By default =1, i.e. y-ffts are done by a 
  !! single proc.
  !
CONTAINS
  !
  !----------------------------------------------------------------------------
  SUBROUTINE mp_start_bands( nband_, ntg_, nyfft_, parent_comm )
    !--------------------------------------------------------------------------
    !! Divide processors (of the "parent_comm" group) into nband_ pools.
    !
    IMPLICIT NONE
    !
    INTEGER, INTENT(IN) :: nband_
    !! it must have been previously read from command line argument
    !! by a call to routine \(\texttt{get\_command\_line}\).
    INTEGER, INTENT(IN) :: parent_comm
    !! typically processors of a k-point pool (intra\_pool\_comm)
    INTEGER, INTENT(IN), OPTIONAL :: ntg_, nyfft_
    !
    INTEGER :: parent_nproc = 1, parent_mype = 0
    !

    !
    parent_nproc = mp_size( parent_comm )
    parent_mype  = mp_rank( parent_comm )
    !
    nbgrp = nband_
    !
    IF ( nbgrp < 1 .OR. nbgrp > parent_nproc ) CALL errore( 'mp_start_bands',&
                          'invalid number of band groups, out of range', 1 )
    IF ( MOD( parent_nproc, nbgrp ) /= 0 ) CALL errore( 'mp_start_bands', &
        'n. of band groups  must be divisor of parent_nproc', 1 )
    !
    ! set logical flag so that band parallelization in H\psi is allowed
    ! (can be disabled before calling H\psi if not desired)
    !
    use_bgrp_in_hpsi = ( nbgrp > 1 )
    ! 
    ! ... Set number of processors per band group
    !
    nproc_bgrp = parent_nproc / nbgrp
    !
    ! ... set index of band group for this processor   ( 0 : nbgrp - 1 )
    !
    my_bgrp_id = parent_mype / nproc_bgrp
    !
    ! ... set index of processor within the image ( 0 : nproc_image - 1 )
    !
    me_bgrp    = MOD( parent_mype, nproc_bgrp )
    !
    CALL mp_barrier( parent_comm )
    !
    ! ... the intra_bgrp_comm communicator is created
    !
    CALL mp_comm_split( parent_comm, my_bgrp_id, parent_mype, intra_bgrp_comm )
    !
    CALL mp_barrier( parent_comm )
    !
    ! ... the inter_bgrp_comm communicator is created                     
    !     
    CALL mp_comm_split( parent_comm, me_bgrp, parent_mype, inter_bgrp_comm )  
    !
    IF ( PRESENT(ntg_) ) THEN
       ntask_groups = ntg_
    END IF
    IF ( PRESENT(nyfft_) ) THEN
       nyfft = nyfft_
    END IF
    call errore('mp_bands',' nyfft value incompatible with nproc_bgrp ', MOD(nproc_bgrp, nyfft) )
    !

    RETURN
    !
  END SUBROUTINE mp_start_bands
  !
END MODULE mp_bands
!# 1 "becmod.f90"
!# 1 "<built-in>"
!# 1 "<command-line>"
!# 1 "/workspace/q-e/Modules//"
!# 1 "becmod.f90"
!
! Copyright (C) 2001-2024 Quantum ESPRESSO Foundation
! This file is distributed under the terms of the
! GNU General Public License. See the file `License'
! in the root directory of the present distribution,
! or http://www.gnu.org/copyleft/gpl.txt .
!
!----------------------------------------------------------------------------
MODULE becmod
  !---------------------------------------------------------------------------
  !! This module contains \(\langle\text{beta}|\text{psi}\rangle\) - used
  !! in \(\texttt{h_psi}\), \(\texttt{s_psi}\) and many other places.  
  !! \(\texttt{calbec}\) is an interface calculating \(\text{betapsi}(i,j) =
  !! \langle \text{beta}(i)|\text{psi}(j)\rangle \) (the sum is over \(\text{npw}\) 
  !! components) or \( \text{betapsi}(i,s,j)= \langle\text{beta}(i)|\text{psi}(s,j)
  !! \rangle\) (s=polarization index).
  !
  USE kinds,            ONLY : DP, offload_kind_acc, offload_kind_cpu, offload_kind_omp
  USE control_flags,    ONLY : gamma_only, smallmem, offload_acc, offload_cpu, offload_omp
  USE gvect,            ONLY : gstart
  USE noncollin_module, ONLY : noncolin, npol
  !
  SAVE
  !
  TYPE bec_type
     REAL(8),   ALLOCATABLE :: r(:,:)
     !! appropriate for gammaonly
     COMPLEX(8),ALLOCATABLE :: k(:,:)
     !! appropriate for generic k
     COMPLEX(8),ALLOCATABLE :: nc(:,:,:)
     !! appropriate for noncolin
     INTEGER :: nbnd
  END TYPE bec_type
  !
  TYPE (bec_type) :: becp
  !! \(\langle\text{beta}|\text{psi}\rangle\)
  !
  PRIVATE
  !
  INTERFACE calbec
     !
     MODULE PROCEDURE &
!                     usage: call calbec( offload_type, beta, psi, betapsi )
!                             - beta, psi, betapsi can be CPU, OpenACC (or OpenMP5), 
!                             - CPU, OpenACC (and OpenMP5) cases are distinguished by type(offload_type)
                      calbec_k_acc, calbec_gamma_acc, calbec_nc_acc, calbec_bec_type_acc, &
                      calbec_k_cpu, calbec_gamma_cpu, calbec_nc_cpu, calbec_bec_type_cpu, &
!                     usage: call calbec( beta, psi, betapsi ) ("old" way to call calbec on CPU)
!                             - beta, psi, betapsi are CPU-only 
!                             - this allows to keep unchanged ALL the "old" calbec calls in the code
                      calbec_k,     calbec_gamma,     calbec_nc,     calbec_bec_type
     !
  END INTERFACE
  !
  INTERFACE becscal
     !
     MODULE PROCEDURE becscal_nck, becscal_gamma
     !
  END INTERFACE
  !
  INTERFACE becupdate
     !
     MODULE PROCEDURE becupdate_0D_cpu, becupdate_1D_cpu, becupdate_2D_cpu, &
                      becupdate_0D_acc, becupdate_1D_acc, becupdate_2D_acc 
     !
  END INTERFACE
  !
  PUBLIC :: bec_type, becp, calbec, beccopy, becscal, becupdate, is_allocated_bec_type, &
            allocate_bec_type,     deallocate_bec_type, &
            allocate_bec_type_acc, deallocate_bec_type_acc
  !
CONTAINS
  !
  !-----------------------------------------------------------------------
  SUBROUTINE calbec_bec_type_acc ( offload, npw, beta, psi, betapsi, nbnd )
    !-----------------------------------------------------------------------
    !
    ! beta, psi, betapsi, are assumed OpenACC data on GPU
    !
    IMPLICIT NONE
    TYPE(offload_kind_acc), INTENT(IN) :: offload
    COMPLEX (8), INTENT (in) :: beta(:,:), psi(:,:)
    TYPE (bec_type), INTENT (inout) :: betapsi ! NB: must be INOUT otherwise
                                               !  the allocatd array is lost
    INTEGER, INTENT (in) :: npw
    INTEGER, OPTIONAL :: nbnd
    !
    INTEGER :: local_nbnd
    !
    IF ( present (nbnd) ) THEN
        local_nbnd = nbnd
    ELSE
        local_nbnd = size ( psi, 2)
    ENDIF

    IF ( gamma_only ) THEN
       !
       CALL calbec_gamma_acc ( offload_acc, npw, beta, psi, betapsi%r, local_nbnd )
       !
    ELSEIF ( noncolin) THEN
       !
       CALL  calbec_nc_acc ( offload_acc, npw, beta, psi, betapsi%nc, local_nbnd )
       !
    ELSE
       !
       CALL  calbec_k_acc ( offload_acc, npw, beta, psi, betapsi%k, local_nbnd )
       !
    ENDIF
    !
    RETURN
    !
  END SUBROUTINE calbec_bec_type_acc
  !
  !-----------------------------------------------------------------------
  SUBROUTINE calbec_bec_type_cpu ( offload, npw, beta, psi, betapsi, nbnd )
    !-----------------------------------------------------------------------
    !
    IMPLICIT NONE
    TYPE(offload_kind_cpu), INTENT(IN) :: offload
    COMPLEX (8), INTENT (in) :: beta(:,:), psi(:,:)
    TYPE (bec_type), INTENT (inout) :: betapsi ! NB: must be INOUT otherwise
                                               !  the allocatd array is lost
    INTEGER, INTENT (in) :: npw
    INTEGER, OPTIONAL :: nbnd
    INTEGER :: m
    !
    IF ( present (nbnd) ) THEN
        m = nbnd
    ELSE
        m = size ( psi, 2)
    ENDIF
    Call calbec_bec_type ( npw, beta, psi, betapsi, m )
    !
    RETURN
    !
  END SUBROUTINE calbec_bec_type_cpu
  !-----------------------------------------------------------------------
  SUBROUTINE calbec_bec_type ( npw, beta, psi, betapsi, nbnd )
    !-----------------------------------------------------------------------
    !
    IMPLICIT NONE
    COMPLEX (8), INTENT (in) :: beta(:,:), psi(:,:)
    TYPE (bec_type), INTENT (inout) :: betapsi ! NB: must be INOUT otherwise
                                               !  the allocatd array is lost
    INTEGER, INTENT (in) :: npw
    INTEGER, OPTIONAL :: nbnd
    !
    INTEGER :: local_nbnd
    !
    IF ( present (nbnd) ) THEN
        local_nbnd = nbnd
    ELSE
        local_nbnd = size ( psi, 2)
    ENDIF

    IF ( gamma_only ) THEN
       !
       CALL calbec_gamma ( npw, beta, psi, betapsi%r, local_nbnd )
       !
    ELSEIF ( noncolin) THEN
       !
       CALL  calbec_nc ( npw, beta, psi, betapsi%nc, local_nbnd )
       !
    ELSE
       !
       CALL  calbec_k ( npw, beta, psi, betapsi%k, local_nbnd )
       !
    ENDIF
    !
    RETURN
    !
  END SUBROUTINE calbec_bec_type
  !
  !-----------------------------------------------------------------------
  SUBROUTINE calbec_gamma_acc ( offload, npw, beta, psi, betapsi, nbnd )
    !-----------------------------------------------------------------------
    !! matrix times matrix with summation index (k=1,npw) running on
    !! half of the G-vectors or PWs - assuming k=0 is the G=0 component:
    !
    !! $$ betapsi(i,j) = 2Re(\sum_k beta^*(i,k)psi(k,j)) + beta^*(i,0)psi(0,j) $$
    !
    ! beta, psi, betapsi, are assumed OpenACC data on GPU
    !
    USE mp_bands, ONLY : intra_bgrp_comm
    USE mp,        ONLY : mp_sum, mp_size
    !
    IMPLICIT NONE
    TYPE(offload_kind_acc), INTENT(IN) :: offload
    COMPLEX (8), INTENT (in) :: beta(:,:), psi(:,:)
    REAL (8), INTENT (out) :: betapsi(:,:)
    INTEGER, INTENT (in) :: npw
    INTEGER, INTENT (in), OPTIONAL :: nbnd
    !
    INTEGER :: nkb, npwx, m
    !
    IF ( present (nbnd) ) THEN
        m = nbnd
    ELSE
        m = size ( psi, 2)
    ENDIF
    !
    nkb = size (beta, 2)
    IF ( nkb == 0 ) RETURN
    !
    CALL start_clock( 'calbec' )
    IF ( npw == 0 ) THEN
      !$acc kernels
      betapsi(:,:)=0.0_8
      !$acc end kernels
    END IF
    npwx= size (beta, 1)
    IF ( npwx /= size (psi, 1) ) CALL errore ('calbec', 'size mismatch', 1)
    IF ( npwx < npw ) CALL errore ('calbec', 'size mismatch', 2)




    IF ( nkb /= size (betapsi,1) .or. m > size (betapsi, 2) ) &
      CALL errore ('calbec', 'size mismatch', 3)
    !
    IF ( m == 1 ) THEN
        !
        !$acc host_data use_device(beta,psi,betapsi)
        CALL MYDGEMV( 'C', 2*npw, nkb, 2.0_8, beta, 2*npwx, psi, 1, 0.0_8, &
                     betapsi, 1 )
        !$acc end host_data
        IF ( gstart == 2 ) THEN
          !$acc kernels
          betapsi(:,1) = betapsi(:,1) - beta(1,:)*psi(1,1)
          !$acc end kernels
        END IF
        !
    ELSE
        !
        !$acc host_data use_device(beta,psi,betapsi)
        CALL MYDGEMM( 'C', 'N', nkb, m, 2*npw, 2.0_8, beta, 2*npwx, psi, &
                    2*npwx, 0.0_8, betapsi, nkb )
        !$acc end host_data
        IF ( gstart == 2 ) THEN
          !$acc host_data use_device(beta,psi,betapsi)
          CALL MYDGER( nkb, m, -1.0_8, beta, 2*npwx, psi, 2*npwx, betapsi, nkb )
          !$acc end host_data
        END IF
        !
    ENDIF
    !
    IF (mp_size(intra_bgrp_comm) > 1) THEN
      !$acc host_data use_device(betapsi)
      CALL mp_sum( betapsi( :, 1:m ), intra_bgrp_comm )
      !$acc end host_data
    END IF
    !
    CALL stop_clock( 'calbec' )
    !
    RETURN
    !
  END SUBROUTINE calbec_gamma_acc
  !
  !-----------------------------------------------------------------------
  SUBROUTINE calbec_gamma_cpu ( offload, npw, beta, psi, betapsi, nbnd )
    !-----------------------------------------------------------------------
    IMPLICIT NONE
    TYPE(offload_kind_cpu), INTENT(IN) :: offload
    COMPLEX (8), INTENT (in) :: beta(:,:), psi(:,:)
    REAL (8), INTENT (out) :: betapsi(:,:)
    INTEGER, INTENT (in) :: npw
    INTEGER, INTENT (in), OPTIONAL :: nbnd
    !
    Call calbec_gamma ( npw, beta, psi, betapsi, nbnd )
    !
  END SUBROUTINE calbec_gamma_cpu
